import {THEMES} from './archive.js';
import {storedTheme} from './tactics.js';
import {goals} from './coaching-tools.js';
export function weekStart(now=Date.now()){const d=new Date(now);d.setHours(0,0,0,0);d.setDate(d.getDate()-(d.getDay()+6)%7);return d.getTime()}
export function eligible(g){return g.side&&g.analysis?.version===2&&g.analysis.complete&&['1-0','0-1','1/2-1/2'].includes(g.headers?.Result)}
export function themeRate(games,theme){let moves=0,errors=0,count=0;for(const g of games.filter(eligible)){count++;for(const d of g.analysis.details.filter(d=>d.side===g.side)){moves++;if(d.loss>.05&&storedTheme(d)===theme)errors++}}return {moves,errors,games:count,rate:moves?errors/moves*100:null}}
export function createGoal(games,username='',now=Date.now()){const start=weekStart(now),baseline=games.filter(g=>eligible(g)&&g.playedAt<start).sort((a,b)=>b.playedAt-a.playedAt).slice(0,30),counts={};for(const g of (baseline.length?baseline:games.filter(eligible)))for(const d of g.analysis.details)if(d.side===g.side&&d.loss>.05){const t=storedTheme(d);counts[t]=(counts[t]||0)+1}const theme=Object.entries(counts).sort((a,b)=>b[1]-a[1])[0]?.[0]||'hanging';return {id:'weekly-'+(username||'local')+'-'+start,start,theme,baseline:themeRate(baseline,theme)}}
export function goalText(goal,games){const current=themeRate(games.filter(g=>g.playedAt>=goal.start),goal.theme),base=goal.baseline;const target=base.rate>0?base.rate*.8:null;const enough=target!==null&&current.games>=3&&current.moves>=30&&base.games>=3&&base.moves>=30;return {title:THEMES[goal.theme],action:goals[goal.theme],text:`Questa settimana: ${current.errors} errori su ${current.moves} mosse personali in ${current.games} partite complete. `+(current.rate===null?'Gioca e analizza per iniziare. ':`Frequenza: ${current.rate.toFixed(1)} ogni 100 mosse. `)+(target===null?'Obiettivo: osservare e ridurre gli errori su questo tema. ':`Riferimento: ${base.rate.toFixed(1)} ogni 100 mosse; obiettivo indicativo ≤ ${target.toFixed(1)}. `)+(enough?(current.rate<=target?'Obiettivo raggiunto nel campione attuale.':'Continua a lavorare su questo tema.'):'Per confrontare i periodi servono almeno 3 partite e 30 mosse in ciascuno.')}}
